import{_ as o,o as t,c as i,ak as d}from"./chunks/framework.CYL5YPWS.js";const p=JSON.parse('{"title":"Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/authentication.md","filePath":"generated/grindr-api/authentication.md"}'),c={name:"grindr-api/authentication.md"};function s(a,e,n,r,l,u){return t(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h1><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to “Sign in”">​</a></h2><p>Make sure you&#39;re passing all <a href="/grindr-api/security-headers">Security headers</a> or you might stumble upon <code>{&quot;code&quot;:28,&quot;message&quot;:&quot;ACCOUNT_BANNED&quot;,&quot;profileId&quot;:null,&quot;type&quot;:1,&quot;reason&quot;:null,&quot;isBanAutomated&quot;:true,&quot;thirdPartyUserIdToShow&quot;:null,&quot;banSubReason&quot;:null}</code> — but don&#39;t fret — it&#39;s a fake error, your account isn&#39;t banned and the API simply blocked your request, not the account. Endpoint selection depends on the <code>recaptcha_first_party</code> <a href="/grindr-api/analytics/assignments">assignment</a>: when disabled (default) sign-in uses <code>/v8/sessions</code>; when enabled the client uses <code>POST /v9/sessions</code> with an extra <code>captchaToken</code>, sharing the same body otherwise.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v8/sessions</span></span></code></pre></div><p>Body:</p><ul><li><code>email</code> — string with email</li><li><code>password</code> — string with password, don&#39;t specify if using <code>authToken</code></li><li><code>authToken</code> — string obtained from login+password flow or <code>null</code></li><li><code>token</code> — FCM (push service) string or <code>null</code></li><li><code>geohash</code> — <a href="/grindr-api/browse/location#geohash">geohash</a> string or <code>null</code></li></ul><p>Response:</p><ul><li><code>profileId</code> — string with numbers, account&#39;s ID</li><li><code>sessionId</code> — <a href="/grindr-api/authentication#session-id">Session ID</a></li><li><code>authToken</code> — string, Auth token for session refresh</li></ul><p>Errors:</p><ul><li><code>ACCOUNT_BANNED</code> — could be malformed request</li><li><code>INVALID_INPUT_PARAMETERS</code> — incorrect credentials</li></ul><h2 id="sign-in-via-recaptcha" tabindex="-1">Sign in via reCAPTCHA <a class="header-anchor" href="#sign-in-via-recaptcha" aria-label="Permalink to “Sign in via reCAPTCHA”">​</a></h2><p>reCAPTCHA variant of <code>POST /v8/sessions</code>. The client uses this endpoint instead of <code>/v8/sessions</code> only when the <code>recaptcha_first_party</code> <a href="/grindr-api/analytics/assignments">assignment</a> is enabled. That assignment is sent by the server and resolved before login. The body is identical to <code>SessionCreateRequest</code> plus a <code>captchaToken</code> (a reCAPTCHA Enterprise token for the <code>login</code> action). The official client always populates <code>captchaToken</code> here and aborts locally if it can&#39;t obtain one, so a <code>null</code>/absent token never reaches this endpoint from the app.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v9/sessions</span></span></code></pre></div><p>Body:</p><p><a href="/grindr-api/authentication#sessioncreaterequestv9">SessionCreateRequestV9</a></p><p>Response:</p><ul><li><code>profileId</code> — string with numbers, account&#39;s ID</li><li><code>sessionId</code> — <a href="/grindr-api/authentication#session-id">Session ID</a></li><li><code>authToken</code> — string, Auth token for session refresh</li></ul><p>Errors:</p><ul><li><code>ACCOUNT_BANNED</code> — could be malformed request</li><li><code>INVALID_INPUT_PARAMETERS</code> — incorrect credentials; on this endpoint a rejected <code>captchaToken</code> (e.g. expired or low-score) is also a plausible cause — server behavior, not confirmed from the client</li></ul><h2 id="login-via-third-party-wip" tabindex="-1">Login via third party, WIP <a class="header-anchor" href="#login-via-third-party-wip" aria-label="Permalink to “Login via third party, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><p>Single endpoint used for both <strong>initial third-party sign-in</strong> and <strong>third-party session refresh</strong>, distinguished by the request body shape (<code>oneOf</code>).</p><p><strong>Google (vendor <code>2</code>):</strong> the app obtains a Google <em>server auth code</em> on-device (<code>GoogleSignInOptions.requestServerAuthCode(...)</code>), exchanges it for a Google <code>access_token</code> via <a href="#exchange-google-auth-code">Exchange Google auth code</a> (<code>POST /v3/users/thirdparty/exchange</code>), then sends that token here as <code>thirdPartyToken</code> (<code>ThirdPartyRequest</code>). <strong>Facebook (vendor <code>1</code>)</strong> sends its access token directly.</p><p>When <code>registered</code> is <code>true</code>, <code>authenticationResponse</code> carries the session and the client stores <code>authToken</code>, <code>sessionId</code> (JWT), <code>profileId</code>, <code>thirdPartyUserId</code> and <code>thirdPartyUserIdToShow</code>. When <code>registered</code> is <code>false</code>, the identity has no account yet and the client continues to <a href="#create-third-party-account">Create third party account</a>.</p><p><strong>Session refresh</strong> reuses this same URL with <code>ThirdPartySessionRequest</code> (<code>{ thirdPartyUserId, authToken, geohash }</code>): the provider token is <strong>not</strong> re-sent — only the stable <code>thirdPartyUserId</code> and the rolling Grindr <code>authToken</code>. The response is the same <code>ThirdPartyAuthResponse</code>, yielding a fresh <code>sessionId</code> (JWT) and a rotated <code>authToken</code>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v8/sessions/thirdparty</span></span></code></pre></div><p>Body:</p><p>One of:</p><ul><li><a href="/grindr-api/authentication#thirdpartyrequest">ThirdPartyRequest</a></li><li><a href="/grindr-api/authentication#thirdpartysessionrequest">ThirdPartySessionRequest</a></li></ul><p>Response:</p><ul><li><code>registered</code> — boolean, <code>true</code> if a Grindr account is already linked to this provider identity.</li><li><code>thirdPartyUserInfo</code> — <a href="/grindr-api/shared-types#undocumentedobject">UndocumentedObject</a>, Provider profile info used to pre-fill account creation when <code>registered</code> is <code>false</code>. or <code>null</code></li><li><code>authenticationResponse</code> — <a href="/grindr-api/authentication#thirdpartyauthenticationresponse">ThirdPartyAuthenticationResponse</a>, Session payload, present when <code>registered</code> is <code>true</code>. or <code>null</code></li></ul><h2 id="exchange-google-auth-code-wip" tabindex="-1">Exchange Google auth code, WIP <a class="header-anchor" href="#exchange-google-auth-code-wip" aria-label="Permalink to “Exchange Google auth code, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><p>First step of the <strong>Google</strong> sign-in flow. The app sends the Google <em>server auth code</em> (<code>serverAuthCode</code> from the native Google Sign-In result, requested against server client id <code>1036042917246-68g7siev1clho9lhqevahao9hlbpvssf.apps.googleusercontent.com</code>). The backend holds the matching web-client secret, performs the authorization-code → token exchange with Google, and returns the Google OAuth tokens. The client keeps <code>access_token</code> and passes it as <code>thirdPartyToken</code> to <a href="#login-via-third-party">Login via third party</a>. Session refreshes do not repeat this step.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v3/users/thirdparty/exchange</span></span></code></pre></div><p>Body:</p><ul><li><code>code</code> — string, Google OAuth 2.0 server auth code (<code>serverAuthCode</code> from the Google Sign-In result).</li></ul><p>Response:</p><ul><li><code>access_token</code> — string, Google OAuth access token. Used as <code>thirdPartyToken</code> in <code>POST /v8/sessions/thirdparty</code>.</li><li><code>token_type</code> — string, OAuth token type, e.g. <code>&quot;Bearer&quot;</code>.</li><li><code>id_token</code> — Google OpenID Connect ID token (JWT).</li><li><code>expires_in</code> — long integer, Access token lifetime in seconds.</li></ul><h2 id="sessioncreaterequest" tabindex="-1">SessionCreateRequest <a class="header-anchor" href="#sessioncreaterequest" aria-label="Permalink to “SessionCreateRequest”">​</a></h2><ul><li><code>email</code> — string with email</li><li><code>password</code> — string with password, don&#39;t specify if using <code>authToken</code></li><li><code>authToken</code> — string obtained from login+password flow or <code>null</code></li><li><code>token</code> — FCM (push service) string or <code>null</code></li><li><code>geohash</code> — <a href="/grindr-api/browse/location#geohash">geohash</a> string or <code>null</code></li></ul><h2 id="sessioncreaterequestv9" tabindex="-1">SessionCreateRequestV9 <a class="header-anchor" href="#sessioncreaterequestv9" aria-label="Permalink to “SessionCreateRequestV9”">​</a></h2><p>Request body for <a href="#sign-in-via-recaptcha">Sign in via reCAPTCHA</a> (<code>POST /v9/sessions</code>). Identical to <code>SessionCreateRequest</code> plus one extra field, <code>captchaToken</code>. The client uses this shape only when the <code>recaptcha_first_party</code> <a href="/grindr-api/analytics/assignments">assignment</a> is enabled for the device.</p><ul><li><em>everything from <a href="/grindr-api/authentication#sessioncreaterequest">SessionCreateRequest</a></em></li><li><code>captchaToken</code> — string, reCAPTCHA Enterprise token for the <code>FirstPartyLogin</code> action. Non-null for the email + password sign-in; <code>null</code> for the <code>authToken</code> session-refresh flow. The token is only fetched by the device when the <code>recaptcha_first_party</code> assignment is enabled.</li></ul><h2 id="accountbannederror" tabindex="-1">AccountBannedError <a class="header-anchor" href="#accountbannederror" aria-label="Permalink to “AccountBannedError”">​</a></h2><p>Error body from sign-in / session refresh when the account, device, or network is restricted. <code>code</code> 28 (<code>ACCOUNT_BANNED</code>) is often a false positive from missing/invalid security headers, not a real ban.</p><ul><li><code>code</code> — integer</li><li><code>message</code> — string</li><li><code>profileId</code> — string or <code>null</code>, optional</li><li><code>type</code> — integer or <code>null</code>, optional</li><li><code>reason</code> — <a href="/grindr-api/authentication#banreason">BanReason</a> or <code>null</code>, optional</li><li><code>banSubReason</code> — <a href="/grindr-api/authentication#bansubreason">BanSubReason</a> or <code>null</code>, optional</li><li><code>isBanAutomated</code> — boolean or <code>null</code>, optional</li><li><code>thirdPartyUserIdToShow</code> — string or <code>null</code>, optional</li><li><code>mail</code> — string or <code>null</code>, optional</li><li><code>phoneNumber</code> — string or <code>null</code>, optional</li><li><code>dialCode</code> — string or <code>null</code>, optional</li></ul><h2 id="banreason" tabindex="-1">BanReason <a class="header-anchor" href="#banreason" aria-label="Permalink to “BanReason”">​</a></h2><p>Account ban reason (timed-ban classification), from the JWT <code>banDetails.reason</code> claim. Unknown values map to <code>Safety &amp; Privacy</code> on the client.</p><ul><li><code>&quot;Harassment&quot;</code></li><li><code>&quot;Impersonation&quot;</code></li><li><code>&quot;Underage User&quot;</code></li><li><code>&quot;Seeking Underage / Child Endangerment&quot;</code></li><li><code>&quot;Underage Impersonation / Vigilante Account&quot;</code></li><li><code>&quot;Commercial Use / Advertising / Promotion&quot;</code></li><li><code>&quot;Sexual Solicitation&quot;</code></li><li><code>&quot;Illegal Drug Related Content&quot;</code></li><li><code>&quot;Drug Selling&quot;</code></li><li><code>&quot;Hate Speech / Discrimination / Hateful Content&quot;</code></li><li><code>&quot;Serious Offline Incident&quot;</code></li><li><code>&quot;Scam / Spam&quot;</code></li><li><code>&quot;Underage - 12 and under&quot;</code></li><li><code>&quot;Safety &amp; Privacy&quot;</code></li><li><code>&quot;TRUST_VENDOR_REJECTED&quot;</code></li></ul><h2 id="bansubreason" tabindex="-1">BanSubReason <a class="header-anchor" href="#bansubreason" aria-label="Permalink to “BanSubReason”">​</a></h2><p>Account ban sub-reason, from the JWT <code>banDetails.subReason</code> claim and the sign-in ban error <code>banSubReason</code>. Unknown values map to <code>Other</code> on the client.</p><ul><li><code>&quot;UNDERAGE_ACCESS&quot;</code></li><li><code>&quot;UNDERAGE_IMPERSONATION&quot;</code></li><li><code>&quot;CHILD_ENDANGERMENT&quot;</code></li><li><code>&quot;UNWANTED_MESSAGING&quot;</code></li><li><code>&quot;PROFILE_SPAM&quot;</code></li><li><code>&quot;PHISHING_AND_FRAUD&quot;</code></li><li><code>&quot;BOT_ACTIVITY&quot;</code></li><li><code>&quot;DRUG_SALES&quot;</code></li><li><code>&quot;FREQUENT_DRUG_SOLICITATION&quot;</code></li><li><code>&quot;OCCASIONAL_DRUG_SOLICITATION&quot;</code></li><li><code>&quot;DRUG_PROMOTION&quot;</code></li><li><code>&quot;NON_ILLICIT_SUBSTANCES&quot;</code></li><li><code>&quot;PAID_SEXUAL_SERVICES&quot;</code></li><li><code>&quot;MILD_SOLICITATION&quot;</code></li><li><code>&quot;SALE_OF_SEXUAL_CONTENT&quot;</code></li><li><code>&quot;MILD_INSULTS&quot;</code></li><li><code>&quot;BULLYING&quot;</code></li><li><code>&quot;HATE_SPEECH&quot;</code></li><li><code>&quot;BLACKMAIL_AND_THREATS&quot;</code></li><li><code>&quot;PRIVACY_VIOLATIONS&quot;</code></li><li><code>&quot;IMPERSONATION&quot;</code></li><li><code>&quot;CONSENT_VIOLATIONS&quot;</code></li><li><code>&quot;OFFLINE_INCIDENTS&quot;</code></li><li><code>&quot;GENERAL_ADVERTISING&quot;</code></li><li><code>&quot;BUSINESS_SOLICITATION&quot;</code></li><li><code>&quot;TRANSACTIONAL_SERVICES&quot;</code></li><li><code>&quot;SCAMS_AND_PROMOTIONS&quot;</code></li><li><code>&quot;BLOCK_DECISION&quot;</code></li><li><code>&quot;Other&quot;</code></li></ul><h2 id="authsessionresponse" tabindex="-1">AuthSessionResponse <a class="header-anchor" href="#authsessionresponse" aria-label="Permalink to “AuthSessionResponse”">​</a></h2><ul><li><code>profileId</code> — string with numbers, account&#39;s ID</li><li><code>sessionId</code> — <a href="/grindr-api/authentication#session-id">Session ID</a></li><li><code>authToken</code> — string, Auth token for session refresh</li></ul><h2 id="googleaccesstokenrequest" tabindex="-1">GoogleAccessTokenRequest <a class="header-anchor" href="#googleaccesstokenrequest" aria-label="Permalink to “GoogleAccessTokenRequest”">​</a></h2><p>Request body for <a href="#exchange-google-auth-code">Exchange Google auth code</a> (<code>POST /v3/users/thirdparty/exchange</code>). Wraps the Google <em>server auth code</em> obtained on-device from native Google Sign-In.</p><ul><li><code>code</code> — string, Google OAuth 2.0 server auth code (<code>serverAuthCode</code> from the Google Sign-In result).</li></ul><h2 id="googleaccesstokenresponse" tabindex="-1">GoogleAccessTokenResponse <a class="header-anchor" href="#googleaccesstokenresponse" aria-label="Permalink to “GoogleAccessTokenResponse”">​</a></h2><p>Response from <a href="#exchange-google-auth-code">Exchange Google auth code</a>. Standard Google OAuth 2.0 token payload returned after the backend exchanges the server auth code. The client keeps only <code>access_token</code>, which it passes as <code>thirdPartyToken</code> to <a href="#login-via-third-party">Login via third party</a>.</p><ul><li><code>access_token</code> — string, Google OAuth access token. Used as <code>thirdPartyToken</code> in <code>POST /v8/sessions/thirdparty</code>.</li><li><code>token_type</code> — string, OAuth token type, e.g. <code>&quot;Bearer&quot;</code>.</li><li><code>id_token</code> — Google OpenID Connect ID token (JWT).</li><li><code>expires_in</code> — long integer, Access token lifetime in seconds.</li></ul><h2 id="thirdpartyrequest" tabindex="-1">ThirdPartyRequest <a class="header-anchor" href="#thirdpartyrequest" aria-label="Permalink to “ThirdPartyRequest”">​</a></h2><p>Request body for the <strong>initial</strong> <a href="#login-via-third-party">Login via third party</a> (<code>POST /v8/sessions/thirdparty</code>). For Google, <code>thirdPartyToken</code> is the <code>access_token</code> from <a href="#exchange-google-auth-code">Exchange Google auth code</a>; for Facebook it is the Facebook access token.</p><ul><li><code>thirdPartyVendor</code> — integer, <code>1</code> — Facebook, <code>2</code> — Google</li><li><code>thirdPartyToken</code> — string, Provider access token (Google <code>access_token</code> / Facebook token).</li><li><code>geohash</code> — <a href="/grindr-api/browse/location#geohash">geohash</a> string or <code>null</code>, optional</li></ul><h2 id="thirdpartysessionrequest" tabindex="-1">ThirdPartySessionRequest <a class="header-anchor" href="#thirdpartysessionrequest" aria-label="Permalink to “ThirdPartySessionRequest”">​</a></h2><p>Request body for <strong>session refresh</strong> via third party, sent to the same <code>POST /v8/sessions/thirdparty</code> endpoint as the initial login. Used once a <code>thirdPartyUserId</code> is stored (account created/logged in via Google or Facebook). The provider token is <strong>not</strong> re-sent — only the stable <code>thirdPartyUserId</code> plus the stored Grindr <code>authToken</code>.</p><ul><li><code>thirdPartyUserId</code> — string, Stable provider user id from the previous login (<code>authenticationResponse.thirdPartyUserId</code>).</li><li><code>authToken</code> — string, Grindr <code>authToken</code> from the previous session (rotated on every refresh).</li><li><code>geohash</code> — <a href="/grindr-api/browse/location#geohash">geohash</a> string or <code>null</code>, optional</li></ul><h2 id="thirdpartyauthenticationresponse" tabindex="-1">ThirdPartyAuthenticationResponse <a class="header-anchor" href="#thirdpartyauthenticationresponse" aria-label="Permalink to “ThirdPartyAuthenticationResponse”">​</a></h2><p>Session payload nested in <code>ThirdPartyAuthResponse.authenticationResponse</code>; present when <code>registered</code> is <code>true</code>. <code>sessionId</code> is the same JWT as in <code>AuthSessionResponse</code>.</p><ul><li><code>profileId</code> — string, Account ID.</li><li><code>sessionId</code> — <a href="/grindr-api/authentication#session-id">Session ID</a></li><li><code>authToken</code> — string, Auth token used for session refresh.</li><li><code>thirdPartyUserId</code> — string, Stable provider user id; persisted and re-sent as <code>thirdPartyUserId</code> on refresh.</li><li><code>thirdPartyUserIdToShow</code> — Display variant of the provider user id (e.g. email/handle).</li></ul><h2 id="thirdpartyauthresponse" tabindex="-1">ThirdPartyAuthResponse <a class="header-anchor" href="#thirdpartyauthresponse" aria-label="Permalink to “ThirdPartyAuthResponse”">​</a></h2><p>Response from <a href="#login-via-third-party">Login via third party</a> and from third-party session refresh. When <code>registered</code> is <code>true</code>, <code>authenticationResponse</code> carries the session. When <code>registered</code> is <code>false</code>, no account is linked yet and the client proceeds to <a href="#create-third-party-account">Create third party account</a> using <code>thirdPartyUserInfo</code>.</p><ul><li><code>registered</code> — boolean, <code>true</code> if a Grindr account is already linked to this provider identity.</li><li><code>thirdPartyUserInfo</code> — <a href="/grindr-api/shared-types#undocumentedobject">UndocumentedObject</a>, Provider profile info used to pre-fill account creation when <code>registered</code> is <code>false</code>. or <code>null</code>, optional</li><li><code>authenticationResponse</code> — <a href="/grindr-api/authentication#thirdpartyauthenticationresponse">ThirdPartyAuthenticationResponse</a>, Session payload, present when <code>registered</code> is <code>true</code>. or <code>null</code>, optional</li></ul><h2 id="session-id" tabindex="-1">Session ID <a class="header-anchor" href="#session-id" aria-label="Permalink to “Session ID”">​</a></h2><p>JWT obtained from authentication flow. Decoded JWT content:</p><p>Headers claims structure:</p><ul><li><code>kid</code> — key ID</li><li><code>alg</code> — <code>&quot;RS256&quot;</code></li><li><code>typ</code> — <code>&quot;JWT&quot;</code></li></ul><p>Payload claims:</p><ul><li><code>exp</code> — number, unix timestamp in seconds defining token expiration date</li><li><code>profileId</code> — string with numbers, account&#39;s ID</li><li><code>roles</code> — unknown array, appears to be empty</li><li><code>features</code> — array of strings, e.g. <code>&quot;HidePremiumStore&quot;</code>, <code>&quot;CreateVideoCall&quot;</code>, <code>&quot;VideoCallDailyFree&quot;</code></li><li><code>featureFlags</code> — array of strings, e.g. <code>&quot;profile-insights&quot;</code>, <code>&quot;online-until-updates&quot;</code>, <code>&quot;enable-account-filters-bulk-exposure&quot;</code>, <code>&quot;a-list-v3&quot;</code>, <code>&quot;discover-v2&quot;</code>, <code>&quot;boost_purchase_fixes&quot;</code>, <code>&quot;discover-studfinder-upsell&quot;</code></li><li><code>experiments</code> — object with experiment name → variant string, known keys: <ul><li><code>explore-paywall-profiles</code> — string, e.g. <code>&quot;test&quot;</code></li><li><code>limiting_chat_credits_from_unlimited_to_5_for_xtra_users_in_explore</code> — string, e.g. <code>&quot;treatment&quot;</code></li><li><code>validation-aa-backend-profileid</code> — string, e.g. <code>&quot;test&quot;</code></li><li><code>grindr-core-day-pass</code> — string, e.g. <code>&quot;control&quot;</code></li><li><code>llm-age-verification-methods</code> — string, e.g. <code>&quot;variant_b&quot;</code></li><li><code>trans_tribe_filtering_changes</code> — string, e.g. <code>&quot;Test&quot;</code></li><li><code>green_dot_v2</code> — string, e.g. <code>&quot;treatment-1&quot;</code></li><li><code>sponsored-profiles-cascade-selection-mode</code> — string, e.g. <code>&quot;treatment&quot;</code></li><li><code>read-receipt-ad-reward</code> — string, e.g. <code>&quot;variant_2&quot;</code></li><li><code>taps-paywall</code> — string, e.g. <code>&quot;treatment-1&quot;</code></li><li><code>explore-insertables-v1</code> — string, e.g. <code>&quot;treatment-insertables-below-mpu&quot;</code></li><li><code>reduce_number_of_free_profiles_from_99_to_90</code> — string, e.g. <code>&quot;test&quot;</code></li><li><code>cascade-mpu-explore-studfinder-2026-03-12</code> — string, e.g. <code>&quot;control&quot;</code></li><li><code>reduce_number_of_results_with_age_filter_for_free_users</code> — string, e.g. <code>&quot;test&quot;</code></li><li><code>mpu-heuristic-algorithm-optimizations-q125</code> — string, e.g. <code>&quot;control&quot;</code></li><li><code>ships_in_the_night_v3</code> — string, e.g. <code>&quot;treatment&quot;</code></li><li><code>cascade-mpu-disable-poc-heuristic-2026-03-02</code> — string, e.g. <code>&quot;treatment&quot;</code></li><li><code>for-you-recsys-v1_1</code> — string, e.g. <code>&quot;control&quot;</code></li><li><code>cascade-mpu-studfinder-profile-limit-2026-03-12</code> — string, e.g. <code>&quot;treatment&quot;</code></li><li><code>reduce_free_user_results_with_any_filter</code> — string, e.g. <code>&quot;control&quot;</code></li><li><code>cascade-mpu-studfinder-unlimited-2026-02-02</code> — string, e.g. <code>&quot;treatment&quot;</code></li><li><code>mpu-rest-of-world</code> — string, e.g. <code>&quot;treatment&quot;</code></li><li><code>top_18_mpu_profiles_are_online_in_extended_cascade_and_explore</code> — string, e.g. <code>&quot;control&quot;</code></li><li><code>for-you-v2</code> — string, e.g. <code>&quot;Test&quot;</code></li><li><code>rewarded-ads-viewed-me-v2</code> — string, e.g. <code>&quot;variant_1&quot;</code></li><li><code>mega-boost-v1</code> — string, e.g. <code>&quot;mega-boost-low&quot;</code></li></ul></li><li><code>systemTime</code> — unix timestamp in milliseconds</li><li><code>upsells</code> — unknown object, appears to be empty</li><li><code>restriction</code> — string or <code>null</code>; account restriction type, one of <code>&quot;AGE_RESTRICTED&quot;</code>, <code>&quot;TIMED_BAN&quot;</code>, <code>&quot;TRUST_VENDOR_REJECTED&quot;</code>; absent/<code>null</code> when unrestricted</li><li><code>restrictionReason</code> — string or <code>null</code>; for <code>AGE_RESTRICTED</code> one of <code>&quot;UK_VERIFICATION_REQUIRED&quot;</code>, <code>&quot;BR_VERIFICATION_REQUIRED&quot;</code>, <code>&quot;AU_VERIFICATION_REQUIRED&quot;</code>, <code>&quot;BANNED_USER&quot;</code>, <code>&quot;VERIFICATION_REQUESTED&quot;</code>; for <code>TRUST_VENDOR_REJECTED</code> a free-form reason</li><li><code>banDetails</code> — object, present when <code>restriction</code> is <code>&quot;TIMED_BAN&quot;</code>: <code>expiryTime</code> (unix seconds), <code>reason</code> (see <code>BanReason</code>), <code>subReason</code> (see <code>BanSubReason</code>), <code>isAutomated</code>, <code>isAgreementCompleted</code>, <code>systemTime</code> (unix ms)</li><li><code>grit</code> — unknown UUIDv4 string</li></ul>',79)])])}const g=o(c,[["render",s]]);export{p as __pageData,g as default};
